O = {
"c357:xo53_1_98": ("WHO 기준 **BMI 28.5**", "WHO 기준 BMI 25~29.9는 과체중, 30 이상은 비만이에요. 28.5는 **과체중**이에요.", "WHO 기준 BMI 28.5는 **과체중**이다.", "25 과체중, 30 비만", 4),
"c357:xt53_1_98": ("BMI **25~29.9** 구간", "WHO 기준으로 25~29.9는 **과체중**, 30 이상이 비만이에요.", "'비만'으로 바꾸면 틀려요.", "25 과체중, 30 비만", 4),
"c357:xo51_1_95": ("BMI와 **지방 분포**", "BMI는 체중(kg)/키(m)²로 전체 체격만 보여 줘요. 복부 지방 분포는 **허리둘레**로 봐요.", "체질량지수는 지방 **분포**를 보여 주지 못한다(분포는 허리둘레).", "BMI = 체격, 허리둘레 = 분포", 3),
"c357:xt51_1_95": ("갈비뼈 아래와 엉덩뼈능선 **중간**", "12번째 갈비뼈 아래와 엉덩뼈능선 중간에서 재는 복부비만 지표는 **허리둘레**예요.", "'체질량지수'로 바꾸면 틀려요.", "복부비만 = 허리둘레", 3),
"c358:xo53_1_61": ("관절운동범위 측정 **자세**", "근육·힘줄이 긴장되면 운동범위가 줄어 보이므로 **긴장을 뺀** 자세에서 재요. 몸쪽 분절을 고정해 대상작용도 막아요.", "관절운동범위는 근육·힘줄의 **긴장을 뺀** 자세에서 잰다.", "느슨하게, 몸쪽 고정", 3),
"c358:xo53_1_62": ("**뒤침**의 운동팔 위치", "아래팔 뒤침은 **손바닥면**에서, 엎침은 손등면에서 재요.", "뒤침은 **손바닥면**, 엎침은 손등면에서 측정한다.", "뒤침 손바닥, 엎침 손등", 3),
"c358:xo53_1_63": ("팔꿈치머리 축 + **자뼈** 운동팔", "어깨 90° 벌림·팔꿉 90° 굽힘에서 팔꿈치머리 축, 자뼈 운동팔로 재는 것은 어깨 **돌림(안쪽·바깥)** 이에요. 수평모음은 어깨봉우리에 축을 둬요.", "이 방법은 어깨 **돌림**을 재는 것이다(수평모음은 어깨봉우리 축).", "팔꿈치머리 축 = 돌림", 4),
"c358:xo53_1_64": ("엉덩관절 **벌림** 축", "엉덩관절 벌림은 **위앞엉덩뼈가시**에 축을 두고, 운동팔은 넙다리 앞 정중선에 맞춰요. 큰돌기는 굽힘·폄의 축이에요.", "엉덩관절 벌림 측정 축은 **위앞엉덩뼈가시**다.", "벌림 = ASIS, 굽힘·폄 = 큰돌기", 4),
"c358:xo52_1_62": ("**엎침**의 운동팔 위치", "엎침은 **손등쪽** 두 붓돌기 선에 운동팔을 둬요. 손바닥쪽은 뒤침이에요.", "엎침 측정 때 운동팔은 **손등쪽** 두 붓돌기 선에 둔다.", "엎침 손등, 뒤침 손바닥", 3),
"c358:xo51_1_62": ("각도계 **고정팔**", "고정팔은 움직이지 않는 **몸쪽** 분절에, 운동팔은 먼쪽 분절에 평행하게 둬요.", "고정팔은 **몸쪽** 분절과 평행하게 둔다.", "고정 = 몸쪽, 운동 = 먼쪽", 3),
"c358:xo51_1_63": ("팔꿉 **굽힘·폄** 축", "팔꿉 굽힘·폄의 축은 **가쪽**위관절융기예요.", "팔꿉 폄 측정 축은 **가쪽**위관절융기다.", "팔꿉 축 = 가쪽", 3),
"c358:xo50_1_61": ("**끝느낌** 평가", "끝느낌은 치료사가 움직이는 **수동** 운동범위 끝에서 느끼는 저항이에요.", "끝느낌은 **수동** 관절운동범위에서 평가한다.", "끝느낌 = 수동", 4),
"c358:xo50_1_62": ("어깨 **벌림** 축", "어깨 벌림 축은 **어깨뼈봉우리 앞쪽**이에요. 부리돌기는 쓰지 않아요.", "어깨 벌림 각도계 축은 **어깨뼈봉우리 앞쪽**에 둔다.", "어깨 벌림 = 봉우리 앞", 3),
"c359:xo53_1_65": ("**골반 올림** 검사", "골반을 위로 끌어올리게 하고 발목을 당겨 저항하는 검사는 **허리네모근** 근력검사예요.", "골반 올림 검사는 **허리네모근**을 본다.", "골반 올리기 = 허리네모근", 4),
"c359:xo53_1_66": ("어깨 **수평벌림** 주동근", "수평벌림 주동근은 **뒤어깨세모근**이에요. 가시위근은 벌림 초기를 담당해요.", "수평벌림의 주동근은 **뒤어깨세모근**이다.", "수평벌림 = 뒤 어깨세모", 4),
"c359:xo53_1_90": ("**넙다리근막긴장근** 작용", "넙다리근막긴장근은 엉덩관절 굽힘과 함께 **안쪽돌림·벌림**을 해요. 대상작용으로 바깥돌림이 생기지 않아요.", "넙다리근막긴장근은 **안쪽돌림·벌림**을 만든다.", "TFL = 굽힘 + 안쪽돌림 + 벌림", 4),
"c359:xo51_1_64": ("목 굽힘 중 **입꼬리**", "목 굽힘 검사에서 입꼬리가 아래로 당겨지면 **넓은목근**의 대상작용이에요.", "입꼬리가 당겨지면 **넓은목근** 대상작용이다.", "입꼬리 = 넓은목근", 3),
"c359:xo51_1_65": ("엉덩관절 벌림 **가(P)** 등급", "벌림 가 등급은 중력을 없앤 **바로누운** 자세에서 검사해요. 옆으로 누운 자세는 중력을 거스르는 양 이상 등급이에요.", "엉덩관절 벌림 가 등급은 **바로누운** 자세에서 검사한다.", "벌림: 가 = 바로누움, 양 = 옆누움", 4),
"c359:xo50_1_64": ("어깨 굽힘 중 **수평모음**", "어깨 굽힘 검사에서 수평모음이 섞이면 **큰가슴근(빗장부분)** 의 대상작용이에요.", "수평모음이 섞이면 **큰가슴근** 대상작용이다.", "모음이 섞이면 큰가슴근", 3),
"c359:xo50_1_65": ("무릎 폄 **양(F)** 등급", "무릎 폄 양 등급은 중력을 거스르는 **앉은 자세**에서 검사해요. 옆으로 누운 자세는 가 등급이에요.", "무릎 폄 양 등급은 **앉은 자세**에서 검사한다.", "중력 거스르면 양, 없애면 가", 4),
"c360:xo53_1_99": ("**자기성찰**의 단계", "근거중심 실무는 질문 → 검색 → 평가 → 적용 → 수행평가 순이에요. 자기성찰과 보완은 마지막 **수행평가** 단계예요.", "자기성찰은 마지막 **수행평가** 단계에서 한다.", "돌아보기는 맨 끝", 3),
"c360:xo52_1_96": ("**PICO** 작성 시기", "PICO는 근거를 찾기 전 **첫 단계**인 질문 작성에서 써요.", "PICO는 근거 검색 **전**, 첫 단계에서 작성한다.", "질문부터, 그다음 검색", 4),
"c360:xo51_1_97": ("근거중심 물리치료의 **세 요소**", "연구 근거만이 아니라 **연구 근거 + 임상 경험 + 환자 선호**를 통합해 결정해요.", "근거중심 물리치료는 연구 근거, 임상 경험, 환자 선호를 **통합**해 결정한다.", "근거 + 경험 + 환자", 4),
"c360:xo50_1_96": ("근거중심 실무의 **핵심**", "핵심은 치료사의 선호가 아니라 연구 근거·임상 전문성·**환자 가치**의 통합이에요.", "근거중심 실무의 핵심은 연구 근거·임상 전문성·환자 가치의 **통합**이다.", "치료사 취향은 근거가 아니다", 3),
"c360:xo50_1_97": ("근거 **평가**의 순서", "순서는 질문 → **찾기** → 평가 → 적용 → 결과 평가예요. 찾은 다음에 평가해요.", "근거 평가는 근거 **찾기 다음**에 한다.", "찾고 나서 평가", 3),
"c361:xo53_1_52": ("**환자-대조군** 연구의 지표", "환자-대조군 연구는 과거 노출을 거슬러 보므로 비교위험도를 직접 못 구하고 **교차비**를 구해요. 비교위험도는 코호트 연구예요.", "환자-대조군 연구는 **교차비**를 구한다(비교위험도는 코호트).", "코호트 = 상대위험도, 환자-대조군 = 교차비", 5),
"c361:xt53_1_52": ("환자-대조군 연구의 **장점**", "이미 병이 있는 사람을 모아 과거를 보므로 **희귀하거나 잠복기가 긴 질병**도 연구할 수 있어요.", "'인과관계를 가장 확실히 밝힌다'로 바꾸면 틀려요.", "희귀병 = 환자-대조군", 4),
"c361:xo52_1_97": ("**메타분석**의 정의", "메타분석은 **여러 연구 결과를 통계적으로 통합**하는 연구예요. 한 명의 반응을 반복 측정하는 것은 단일사례연구예요.", "메타분석은 **여러 연구를 통계적으로 통합**하는 연구다.", "메타 = 연구들의 연구", 3),
"c361:xt52_1_97": ("한 명의 **중재 반응**", "한 명(또는 한 집단)의 반응을 기초선과 중재기로 나눠 반복 측정하는 것은 **단일사례연구**예요.", "'메타분석'으로 바꾸면 틀려요.", "한 명 = 단일사례", 3),
"c361:xo51_1_96": ("**상대위험도**를 구하는 연구", "상대위험도는 노출군과 비노출군을 추적하는 **코호트** 연구에서 직접 구해요. 환자-대조군은 교차비예요.", "**코호트 연구**로 상대위험도를 직접 구한다.", "상대위험도 = 코호트", 5),
"c361:xt51_1_96": ("노출군 **장기 추적**", "노출군과 비노출군을 시간에 따라 추적해 발생률을 비교하는 연구가 **코호트 연구**예요.", "'환자-대조군 연구'로 바꾸면 틀려요.", "앞으로 추적 = 코호트", 5),
"c362:xo53_1_100": ("HOAC II **검사전략**", "검사전략(기준)은 가설을 판단할 기준을 정하는 단계예요. 중재법·기간·빈도는 **중재전략** 단계에서 정해요.", "치료 빈도는 **중재전략 수립** 단계에서 정한다.", "얼마나 자주 = 중재전략", 3),
"c362:xt53_1_100": ("중재법·기간·**빈도**", "HOAC II에서 무엇을 얼마나 자주 할지 구체적으로 정하는 단계는 **중재전략 수립**이에요.", "'검사전략 수립'으로 바꾸면 틀려요.", "중재 = 무엇·얼마나", 3),
"c362:xo50_1_98": ("가설 **유지·폐기**", "가설을 유지하거나 폐기하는 것은 **재평가** 단계예요. 초기 개념화는 시작 단계예요.", "가설의 유지·폐기는 **재평가** 단계에서 결정한다.", "다시 보고 버린다 = 재평가", 3),
"c362:xt50_1_98": ("기대 결과가 **없을 때**", "기대한 결과가 없으면 치료를 바꾸고 가설을 유지·폐기하는 단계는 **재평가**예요.", "'초기 개념화'로 바꾸면 틀려요.", "결과 없으면 재평가", 3),
"c362:xo50_1_99": ("HOAC II 순서", "HOAC II는 목표를 세운 뒤 **가설 검증** 단계로 가요. 맞는 문장이에요.", "'가설 검증 후 목표 설정'으로 바꾸면 틀려요.", "목표 먼저, 검증 나중", 2),
"c363:xo53_1_101": ("**검진**과 **평가**", "검진은 자료를 **수집**하는 단계, 자료를 해석·판단하는 것은 **평가** 단계예요.", "자료를 해석해 판단하는 것은 **평가** 단계다.", "모으면 검진, 판단하면 평가", 4),
"c363:xt53_1_101": ("자료 **해석·판단**", "수집한 자료를 해석·판단해 기능 문제를 찾는 단계가 **평가**예요.", "'검진'으로 바꾸면 틀려요.", "판단 = 평가", 4),
"c363:xo52_1_61": ("**비손상측** 먼저", "비손상측을 먼저 측정해 기준을 잡은 뒤 손상측을 평가해요.", "**비손상측**을 먼저 평가하고 손상측은 나중에 평가한다.", "건강한 쪽이 기준", 3),
"c363:xt52_1_61": ("측정·평가 **기록 원칙**", "측정 결과는 **문자·기호·숫자·그림**으로 기록하고, 비손상측을 먼저 측정해요.", "'손상측을 먼저 측정한다'를 덧붙이면 틀려요.", "기록은 누구나 알아보게", 2),
"c363:xo51_1_101": ("**기능 목표** 설정 단계", "기능 목표는 **예후 및 치료계획** 단계에서 정해요. 검진은 자료 수집 단계예요.", "기능 목표는 **예후 및 치료계획** 단계에서 정한다.", "목표 = 예후·계획", 3),
"c363:xt51_1_101": ("\"1주 안에 목발 **10m 왕복**\"", "기간과 기준이 정해진 기능 목표는 **예후 및 치료계획(목표)** 단계에 속해요.", "'검진'으로 바꾸면 틀려요.", "목표 = 예후·계획", 3),
"c364:xo52_1_98": ("ICF **활동**과 **참여**", "활동은 개인의 과제 수행이고, 사회적 역할 수행은 **참여**예요.", "사회적 역할 수행은 ICF의 **참여** 요소다.", "혼자 하는 과제 = 활동, 사회 역할 = 참여", 4),
"c364:xo51_1_100": ("**휠체어 이동** 어려움", "옮겨 앉기·일어서기처럼 개인이 과제를 수행하는 어려움은 **활동제한**이에요. 참여제약은 사회적 역할의 제약이에요.", "휠체어 이동 어려움은 **활동제한**에 해당한다.", "과제 = 활동, 역할 = 참여", 4),
"c364:xo50_1_100": ("**ICIDH**와 **ICF**", "환경요인과 개인요인(배경요인)을 포함한 최신 분류는 **ICF**예요. ICIDH는 그 이전 분류예요.", "배경요인을 포함한 최신 분류는 **ICF**다.", "배경요인 = ICF", 3),
"c364:xo50_2_64": ("**ROM 제한**의 수준", "관절운동범위·근력 같은 것은 **신체 기능(손상)** 수준이에요.", "관절운동범위 제한은 ICF의 **신체 기능·구조** 수준이다.", "몸의 수치 = 신체 기능", 4),
"c365:xo53_1_102": ("**복용 약물**의 기록 위치", "면담으로 얻은 복용약·병력·수술 방법은 **S(주관적)** 에 기록해요.", "복용 약물은 **주관적 정보(S)** 에 기록한다.", "환자가 말한 것 = S", 4),
"c365:xo52_1_101": ("**VAS 점수**의 기록 위치", "VAS처럼 점수로 측정한 값은 **O(객관적)** 에 기록해요.", "VAS 점수는 **객관적 정보(O)** 에 기록한다.", "점수로 잰 것 = O", 4),
"c365:xo51_1_61": ("**목표**의 기록 위치", "S와 O를 바탕으로 정한 문제 목록과 목표는 **A(평가)** 에 기록해요.", "환자의 목표는 **A**에 기록한다.", "문제·목표 = A", 3),
"c365:xo50_1_101": ("**BBS 점수**의 기록 위치", "BBS 같은 측정 점수는 **O(객관적)** 에 기록해요.", "BBS 점수는 **객관적 정보(O)** 에 기록한다.", "측정값 = O", 4),
"c366:xo53_1_85": ("**바델 지수** 해석", "바델 지수는 10항목 0~100점이고, 점수가 높을수록 **자립도가 높아요**.", "바델 지수는 점수가 높을수록 **자립도**가 높다.", "높을수록 혼자 잘한다", 4),
"c366:xo52_1_100": ("척수손상 전용 **3영역 19항목**", "척수손상 전용 3영역 19항목 도구는 **SCIM**이에요. FIM은 18항목(운동 13·인지 5)이에요.", "**SCIM**은 척수손상 전용 3영역 19항목 도구다.", "SCIM 19, FIM 18, 바델 10", 4),
"c366:xo50_1_83": ("**FIM** 구성", "FIM은 **18항목 126점**이에요. 10항목 100점은 바델 지수예요.", "FIM은 **18항목 126점** 만점이다.", "FIM 18·126, 바델 10·100", 5),
"c366:xo50_1_105": ("**FIM 최고점**", "FIM은 18항목 × 7점 = **126점**이 최고점이에요. 100점은 바델 지수예요.", "FIM의 최고점은 **126점**이다.", "18 × 7 = 126", 5),
"c367:xo53_1_103": ("**아동학대** 의심 시", "의료기관 종사 의료기사는 아동학대 **신고의무자**로, 의심되면 시·군·구 또는 수사기관에 신고해야 해요.", "아동학대가 의심되면 시·군·구 또는 수사기관에 **신고**한다.", "의심되면 신고", 3),
"c367:xo53_1_104": ("비하 별명 = **편견**", "환자에게 부정적 낙인을 붙이는 것은 **편견**이에요. 이해관계 충돌은 사적 이익과 직무가 부딪히는 것이에요.", "비하 별명은 **편견**에 해당한다.", "낙인 = 편견, 사익 = 이해충돌", 3),
"c367:xo52_1_102": ("**IRB 심의** 시기", "환자 정보를 연구에 쓰려면 연구 **시작 전**에 IRB 심의를 받고 동의서를 받아요.", "기관생명윤리위원회 심의는 자료를 모으기 **전**에 받는다.", "IRB 먼저, 연구 나중", 3),
"c367:xo52_1_103": ("**격리 사유** 공유", "진료·감염 정보는 개인정보라 친분과 상관없이 **본인 동의 없이** 알려선 안 돼요.", "다른 환자의 격리 사유는 친분이 있어도 **알려 주지 않는다**.", "친해도 비밀", 3),
"c367:xo51_1_102": ("**선임 요구**와 환자 정보", "환자 개인정보는 선임 요청이라도 **본인 동의 없이** 제공하지 않아요.", "선임이 요구해도 **본인 동의 없이** 환자 정보를 제공하지 않는다.", "직급보다 동의", 3),
"c367:xo51_1_103": ("치료 횟수 **부풀림**", "실제보다 치료 횟수를 부풀려 청구하는 것은 **사기**에 해당해요.", "치료 횟수를 부풀린 청구는 **사기**에 해당한다.", "부풀린 청구 = 사기", 3),
"c367:xo50_1_102": ("**의무윤리**와 결과", "결과가 좋으면 선하다고 보는 것은 **공리주의**예요. 의무윤리는 결과와 상관없이 규칙·의무를 지키는 것을 중시해요.", "결과가 좋으면 선한 행동으로 보는 것은 **공리주의**다.", "결과 = 공리주의, 규칙 = 의무윤리", 3),
"c367:xo50_1_103": ("**성별 채용 배제**", "근거 없는 고정관념에 따른 배제는 **편견(차별)** 이에요. 이해충돌이 아니에요.", "성별에 따른 채용 배제는 **편견**에 해당한다.", "고정관념 = 편견", 2),
}
